/**
 * Extracts the sender, subject and message body from a Gmail trigger item.
 * The workflow keeps only normalized text values so later nodes never need
 * direct access to the raw email payload.
 */
const email = $input.first().json;
const headers = email.headers ?? {};
const from = String(email.from ?? headers.from ?? '').trim();
const subject = String(email.subject ?? headers.subject ?? 'Untitled request').trim();
const text = String(email.textPlain ?? email.text ?? email.snippet ?? '').trim();
const html = String(email.textHtml ?? email.html ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const body = text || html || 'No email body was provided.';
const senderEmail = (from.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) ?? [''])[0];
const senderName = from.replace(/<[^>]+>/g, '').replace(senderEmail, '').replace(/["<>]/g, '').trim() || senderEmail || 'External stakeholder';

return [{
  json: {
    messageId: email.id ?? email.messageId ?? '',
    threadId: email.threadId ?? '',
    senderName,
    senderEmail,
    subject,
    body,
    receivedAt: new Date().toISOString(),
  },
}];

/**
 * Applies the public daily automation limit.
 * The starter workflow stores the counter in n8n workflow static data; a
 * production setup can replace this with Firestore or another durable store.
 */
const request = $input.first().json;
const data = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (data.requestQuotaDate !== today) {
  data.requestQuotaDate = today;
  data.requestQuotaUsed = 0;
}
const used = Number(data.requestQuotaUsed ?? 0);
const dailyLimit = 10;
const limitReached = used >= dailyLimit;
if (!limitReached) data.requestQuotaUsed = used + 1;

return [{
  json: {
    ...request,
    quota: {
      date: today,
      used: limitReached ? used : used + 1,
      dailyLimit,
      limitReached,
    },
  },
}];

/**
 * Converts the AI result into the Join task shape stored in Firestore.
 * The description always starts with an AI notice so the board remains clear
 * about automatically generated ticket content.
 */
const emailRequest = $('Extract email request').first().json;
const aiOutput = $input.first().json.output ?? $input.first().json.text ?? $input.first().json;
let parsed = {};
try {
  parsed = typeof aiOutput === 'string' ? JSON.parse(aiOutput) : aiOutput;
} catch {
  parsed = {};
}
const categories = new Set(['user-story', 'technical-task']);
const priorities = new Set(['low', 'medium', 'urgent']);
const fallbackDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const title = String(parsed.title || emailRequest.subject || 'Stakeholder request').trim().slice(0, 120);
const category = categories.has(parsed.category) ? parsed.category : 'user-story';
const priority = priorities.has(parsed.priority) ? parsed.priority : 'medium';
const dueDate = /^\d{4}-\d{2}-\d{2}$/.test(String(parsed.dueDate || '')) ? parsed.dueDate : fallbackDate;
const generatedDescription = String(parsed.description || emailRequest.body).trim();

return [{
  json: {
    task: {
      title,
      description: `[AI-generated from stakeholder email]\n\n${generatedDescription}`,
      dueDate,
      priority,
      status: 'triage',
      category,
      assignedTo: [],
      subtasks: [],
      source: 'email',
      creator: {
        type: 'external',
        name: emailRequest.senderName,
        email: emailRequest.senderEmail,
        uid: '',
      },
    },
    emailRequest,
  },
}];
